{"script": "# Ensure 'dataaccess' group exists
groupmod --gid 1001 dataaccess 2>/dev/null || groupadd -g 1001 dataaccess

# Set /data's group ownership and permissions
chgrp -R dataaccess /data
find /data -type d -exec chmod g+s {} \;
find /data -type f -exec chmod g+rw {} \; 

# Configure umask for group inheritance (applies to new files/dirs)
echo "umask 002" >> /etc/profile.d/dataaccess.sh && chmod +x /etc/profile.d/dataaccess.sh

# Verify changes
echo "Configuration complete. Group ownership and permissions set.""}

